(function (global) {
  const TEMPLATE_NAME = "REVENUE VERSI EDP MNJ";
  global.readEthicalHjpData = async function (file) {
    if (!global.XLSX) throw new Error("Komponen spreadsheet belum dimuat.");
    const sourceBook = global.XLSX.read(await file.arrayBuffer(), { type: "array", cellDates: true });
    const monthAliases = { JAN:1, JANUARI:1, FEB:2, FEBRUARI:2, MAR:3, MARET:3, APR:4, APRIL:4, MAY:5, MEI:5, JUN:6, JUNI:6, JUL:7, JULI:7, AUG:8, AGS:8, AGUSTUS:8, SEP:9, SEPTEMBER:9, OCT:10, OKT:10, OKTOBER:10, NOV:11, NOVEMBER:11, DEC:12, DES:12, DESEMBER:12 };
    const text = (sheet, row, column) => String(sheet[global.XLSX.utils.encode_cell({ r: row - 1, c: column - 1 })]?.v ?? "").trim().toUpperCase().replace(/\s+/g, " ");
    const sourceSheet = sourceBook.SheetNames.map((name) => sourceBook.Sheets[name]).find((sheet) => /TARGET\s+ETHICAL/i.test(text(sheet, 1, 1))) || sourceBook.Sheets[sourceBook.SheetNames[0]];
    if (!sourceSheet) throw new Error("Sheet raw Ethical tidak ditemukan.");
    const range = global.XLSX.utils.decode_range(sourceSheet["!ref"] || "A1:A1");
    const monthColumns = new Map();
    for (let c = 0; c <= range.e.c; c++) {
      const label = text(sourceSheet, 3, c + 1).replace(/[^A-Z]/g, "");
      if (monthAliases[label]) monthColumns.set(monthAliases[label], c + 1);
    }
    if (monthColumns.size !== 12) throw new Error("Header JAN–DES pada baris 3 raw Ethical tidak lengkap.");
    const findSection = (startPattern, totalPattern) => {
      let start = -1, end = -1, totalRow = -1;
      for (let r = 1; r <= range.e.r + 1; r++) {
        const label = text(sourceSheet, r, 2);
        if (start < 0 && startPattern.test(label) && !/^TOTAL\b/.test(label)) start = r + 1;
        else if (start >= 0 && totalPattern.test(label)) { end = r - 1; totalRow = r; break; }
      }
      if (start < 0 || end < start) throw new Error("Bagian produk raw Ethical tidak lengkap: " + startPattern.source);
      return { first: start, last: end, totalRow };
    };
    const existingRows = findSection(/^EX(?:I|SI)STING\s+PRODUCT$/, /^TOTAL\s+EX(?:I|SI)STING\s+PRODUCT$/);
    const streamlineRows = findSection(/^STREAMLINE$/, /^TOTAL\s+STREAMLINE$/);
    const newProductSections = [];
    for (let row = 1; row <= range.e.r + 1; row++) {
      if (!/^NEW\s+PRODUCT(?:\s+20\d{2})?$/.test(text(sourceSheet, row, 2))) continue;
      let totalRow = -1;
      for (let nextRow = row + 1; nextRow <= range.e.r + 1; nextRow++) {
        const label = text(sourceSheet, nextRow, 2);
        if (/^NEW\s+PRODUCT(?:\s+20\d{2})?$/.test(label)) break;
        if (/^TOTAL\s+NEW\s+PRODUCT(?:\s+\d{2,4})?$/.test(label)) { totalRow = nextRow; break; }
      }
      if (totalRow > row + 1) newProductSections.push({ first: row + 1, last: totalRow - 1, totalRow });
    }
    if (newProductSections.length < 2) throw new Error("Bagian NEW PRODUCT dan TOTAL NEW PRODUCT belum lengkap di file raw Ethical.");
    const toNumber = (value) => {
      if (typeof value === "number" && Number.isFinite(value)) return value;
      if (typeof value === "string") { const parsed = Number(value.trim().replace(/\./g, "").replace(",", ".")); if (Number.isFinite(parsed)) return parsed; }
      return 0;
    };
    const target = Array(12).fill(0), actual = Array(12).fill(0);
    const newTarget = Array(12).fill(0), newActual = Array(12).fill(0);
    const hnaExisting = Array(12).fill(0), hnaNew = Array(12).fill(0);
    let populatedCells = 0;
    const sumHjpAcrossRows = (section, column) => {
      let detailTotal = 0;
      let hasDetailValues = false;
      for (let row = section.first; row <= section.last; row++) {
        const value = sourceSheet[global.XLSX.utils.encode_cell({ r: row - 1, c: column - 1 })]?.v;
        if (value !== undefined && value !== null && value !== "") { populatedCells++; hasDetailValues = true; }
        detailTotal += toNumber(value);
      }
      // Gunakan langsung hasil baris TOTAL EXISTING PRODUCT / TOTAL STREAMLINE
      // / TOTAL NEW PRODUCT jika file menyimpan hasil kalkulasinya. Bila cache
      // rumus kosong atau nol sementara rincian tersedia, hitung rincian.
      const totalCell = sourceSheet[global.XLSX.utils.encode_cell({ r: section.totalRow - 1, c: column - 1 })];
      const totalValue = totalCell?.v;
      const hasTotalValue = totalValue !== undefined && totalValue !== null && totalValue !== "";
      if (hasTotalValue && (!totalCell.f || toNumber(totalValue) !== 0)) {
        populatedCells++;
        return toNumber(totalValue);
      }
      if (hasDetailValues) return detailTotal;
      return hasTotalValue && !totalCell.f ? toNumber(totalValue) : 0;
    };
    for (let month = 1; month <= 12; month++) {
      const base = monthColumns.get(month);
      const targetHnaColumn = base + 1; // kolom HNA pada grup Target
      const targetHjpColumn = base + 2; // kolom HJP pada grup Target
      const realHjpColumn = base + 5; // kolom HJP pada grup Real
      if (text(sourceSheet, 4, base) !== "TARGET" || text(sourceSheet, 4, base + 3) !== "REAL"
          || text(sourceSheet, 5, targetHjpColumn) !== "HJP" || text(sourceSheet, 5, realHjpColumn) !== "HJP") {
        throw new Error("Susunan kolom HJP Target/Real tidak sesuai pada bulan " + month + ".");
      }
      // Setara dengan menjumlahkan TOTAL EXISTING PRODUCT dan TOTAL STREAMLINE
      // untuk bulan ini; rincian dipakai agar hasil tetap akurat jika formula
      // total pada file ODS belum memiliki nilai kalkulasi tersimpan.
      target[month - 1] = sumHjpAcrossRows(existingRows, targetHjpColumn)
        + sumHjpAcrossRows(streamlineRows, targetHjpColumn);
      hnaExisting[month - 1] = sumHjpAcrossRows(existingRows, targetHnaColumn)
        + sumHjpAcrossRows(streamlineRows, targetHnaColumn);
      actual[month - 1] = sumHjpAcrossRows(existingRows, realHjpColumn)
        + sumHjpAcrossRows(streamlineRows, realHjpColumn);
      newTarget[month - 1] = newProductSections.reduce((sum, section) => sum + sumHjpAcrossRows(section, targetHjpColumn), 0);
      newActual[month - 1] = newProductSections.reduce((sum, section) => sum + sumHjpAcrossRows(section, realHjpColumn), 0);
      hnaNew[month - 1] = newProductSections.reduce((sum, section) => sum + sumHjpAcrossRows(section, targetHnaColumn), 0);
    }
    if (!populatedCells) throw new Error("Data HJP pada bagian EXISTING PRODUCT dan STREAMLINE masih kosong.");
    const sourceYear = Number((text(sourceSheet, 1, 1).match(/(20\d{2})/) || [])[1]);
    if (!sourceYear) throw new Error("Tahun data Ethical tidak ditemukan pada judul sheet.");
    const hnaTotal = hnaExisting.map((value, index) => value + hnaNew[index]);
    return { year: sourceYear, target, actual, newTarget, newActual, hnaExisting, hnaNew, hnaTotal };
  };
  global.getEthicalHjpData = async function (...years) {
    const endpoint = location.protocol === "file:"
      ? "http://127.0.0.1:8000/dashboard/ethical_api.php"
      : new URL("ethical_api.php", location.href).href;
    let response;
    try { response = await fetch(endpoint, { cache: "no-store" }); }
    catch (_) { throw new Error("Data ETHICAL tidak dapat diambil dari database. Pastikan server PHP berjalan."); }
    const payload = await response.json().catch(() => null);
    if (!response.ok || !payload || payload.success !== true) {
      throw new Error(payload && payload.message ? payload.message : "Data ETHICAL gagal dibaca dari database.");
    }
    const records = Array.isArray(payload.data) ? payload.data : [];
    const candidates = years.map((year) => records.find((record) => Number(record.year) === Number(year))).filter(Boolean);
    const selected = candidates.find((record) => Array.isArray(record.target) && Array.isArray(record.actual)
      && Array.isArray(record.newTarget) && Array.isArray(record.newActual)
      && Array.isArray(record.hnaExisting) && Array.isArray(record.hnaNew));
    if (!selected) {
      throw new Error("Data ETHICAL untuk tahun " + years.join(", ") + " belum ditemukan di database.");
    }
    selected._history = records.filter((record) => record && Number.isInteger(Number(record.year)))
      .sort((a, b) => Number(b.year) - Number(a.year));
    return selected;
  };
  global.replaceEthicalTemplateSheet = async function (workbook, period, hjpData, includeHistory = true) {
    const match = /^(\d{4})-(0[1-9]|1[0-2])$/.exec(String(period || ""));
    const now = new Date();
    const year = match ? Number(match[1]) : now.getFullYear();
    const month = match ? Number(match[2]) : now.getMonth() + 1;
    const previousYear = year - 1;
    const monthNames = ["JAN", "FEB", "MAR", "APR", "MEI", "JUN", "JUL", "AGS", "SEP", "OKT", "NOV", "DES"];
    const rows = Array.from({ length: 62 }, () => Array(18).fill(""));
    const put = (row, col, value) => { rows[row - 1][col - 1] = value; };
    put(1, 1, "Laporan Bulanan"); put(2, 1, "Ethical"); put(2, 3, monthNames[month - 1]);
    const hnaSecondBlock = hjpData && Number(hjpData.year) === year + 1;
    const hnaFirstYear = hnaSecondBlock ? year : (hjpData && Number.isInteger(Number(hjpData.year)) ? Number(hjpData.year) : year);
    put(3, 2, "Bulan"); put(3, 3, `Target Awal (HNA atau Selling Out) ${hnaFirstYear}`); put(3, 6, `Target Awal (HNA atau Selling Out) ${hnaFirstYear + 1}`); put(3, 9, `Bi. Promosi ${hnaFirstYear + 1}`);
    [[3,"Existing"],[4,"NP"],[5,"Total"],[6,"Existing"],[7,"NP"],[8,"Total"],[9,"NON MPP"],[10,"MPP"],[11,"TOTAL"]].forEach(([c,v]) => put(4,c,v));
    monthNames.forEach((name, i) => put(5+i, 2, name)); put(17, 2, hnaFirstYear); put(18, 2, `KUMULATIF S/D ${monthNames[month-1]}`);
    put(21, 2, `ETHICAL ${year}`); put(22, 2, "Bulan"); put(22, 3, "Target Awal (HJP)"); put(22, 6, "Target Rolling (HJP)"); put(22, 9, "MCM"); put(22, 12, "Product Launch");
    [[3,"Existing"],[4,"NP"],[5,"Total"],[6,"Existing"],[7,"NP"],[8,"Total"],[9,"Target"],[10,"Real"],[11,"%"],[12,"Nama"],[13,"Target"],[14,"Realisasi"],[16,"IR"],[17,"PD"],[18,"Total"]].forEach(([c,v]) => put(23,c,v));
    monthNames.forEach((name, i) => put(24+i, 2, name)); put(36,2,year); put(37,2,`KUMULATIF S/D ${monthNames[month-1]}`);
    const addAnnualBlock = (titleRow, headerRow, yearLabel, title) => {
      if (title) put(titleRow,2,title); put(headerRow,2,yearLabel); put(headerRow,3,"PERIODE"); put(headerRow,4,monthNames[month-1]);
      monthNames.forEach((name,i) => put(headerRow,6+i,name[0]+name.slice(1).toLowerCase()));
    };
    const hjpYear = hjpData && Number.isInteger(Number(hjpData.year)) ? Number(hjpData.year) : previousYear;
    addAnnualBlock(40,42,hjpYear,`ETHICAL ${hjpYear} (HJP)`);
    [[43,"MCM (000)","TARGET TOTAL","Target Awal"],[44,"","AKTUAL TOTAL","Aktual"],[45,"","", "%"],[47,"REVENUE (000)","", ""],[49,"TOTAL REVENUE","TARGET TOTAL","Target Awal"],[50,"","AKTUAL TOTAL","Aktual"],[51,"","", "%"],[52,"EXISTING","TARGET TOTAL","Target Awal"],[53,"","AKTUAL TOTAL","Aktual"],[54,"","", "%"],[55,"NEW","TARGET TOTAL","Target Awal"],[56,"","AKTUAL TOTAL","Aktual"],[57,"","", "%"],[59,"","",""],[60,"BIAYA (000)","TARGET TOTAL","Target Awal"],[61,"","AKTUAL TOTAL","Aktual"],[62,"","", "%"]].forEach(([r,b,c,e])=>{ if(b) put(r,2,b); if(c) put(r,3,c); if(e) put(r,5,e); });
    // Blok revenue memakai periode tahunan yang sama seperti struktur sumber.
    [[48,previousYear],[59,previousYear]].forEach(([r,y])=>addAnnualBlock(r-1,r,y,""));
    [[45,42],[51,48],[54,48],[57,48],[62,59]].forEach(([r,periodRow])=>put(r,3,`AKTUAL KUM S/D ${monthNames[month-1]}`));
    const sheet = global.XLSX.utils.aoa_to_sheet(rows);
    if (hjpData) {
      const hnaStartColumn = hjpData.year === year + 1 ? 6 : 3;
      for (let i = 0; i < 12; i++) {
        const targetCell = global.XLSX.utils.encode_cell({ r: 51, c: 5 + i }); // EXISTING > Target Awal
        const actualCell = global.XLSX.utils.encode_cell({ r: 52, c: 5 + i }); // EXISTING > Aktual
        sheet[targetCell] = { t: "n", v: Number(hjpData.target[i]) || 0, z: "#,##0" };
        sheet[actualCell] = { t: "n", v: Number(hjpData.actual[i]) || 0, z: "#,##0" };
        const newTargetCell = global.XLSX.utils.encode_cell({ r: 54, c: 5 + i }); // NEW > Target Awal
        const newActualCell = global.XLSX.utils.encode_cell({ r: 55, c: 5 + i }); // NEW > Aktual
        const newTarget = Array.isArray(hjpData.newTarget) ? Number(hjpData.newTarget[i]) || 0 : 0;
        const newActual = Array.isArray(hjpData.newActual) ? Number(hjpData.newActual[i]) || 0 : 0;
        sheet[newTargetCell] = { t: "n", v: newTarget, z: "#,##0" };
        sheet[newActualCell] = { t: "n", v: newActual, z: "#,##0" };
        const revenueTargetCell = global.XLSX.utils.encode_cell({ r: 48, c: 5 + i }); // TOTAL REVENUE > Target Total
        const revenueActualCell = global.XLSX.utils.encode_cell({ r: 49, c: 5 + i }); // TOTAL REVENUE > Aktual Total
        sheet[revenueTargetCell] = { t: "n", v: (Number(hjpData.target[i]) || 0) + newTarget, z: "#,##0" };
        sheet[revenueActualCell] = { t: "n", v: (Number(hjpData.actual[i]) || 0) + newActual, z: "#,##0" };
        const setPercent = (row, actual, target) => {
          const cell = global.XLSX.utils.encode_cell({ r: row - 1, c: 5 + i });
          if (target) sheet[cell] = { t: "n", v: actual / target, z: "0.00%" };
          else sheet[cell] = { t: "s", v: "" };
        };
        setPercent(51, (Number(hjpData.actual[i]) || 0) + newActual, (Number(hjpData.target[i]) || 0) + newTarget);
        setPercent(54, Number(hjpData.actual[i]) || 0, Number(hjpData.target[i]) || 0);
        setPercent(57, newActual, newTarget);
        if (hnaStartColumn && Array.isArray(hjpData.hnaExisting) && Array.isArray(hjpData.hnaNew)) {
          const existingHna = Number(hjpData.hnaExisting[i]) || 0;
          const newHna = Number(hjpData.hnaNew[i]) || 0;
          const hnaMonthly = [existingHna, newHna, existingHna + newHna];
          hnaMonthly.forEach((value, index) => {
            const cell = global.XLSX.utils.encode_cell({ r: 4 + i, c: hnaStartColumn - 1 + index });
            sheet[cell] = { t: "n", v: value, z: "#,##0" };
          });
        }
      }
      if (hnaStartColumn && Array.isArray(hjpData.hnaExisting) && Array.isArray(hjpData.hnaNew)) {
        const annualExisting = hjpData.hnaExisting.reduce((sum, value) => sum + (Number(value) || 0), 0);
        const annualNew = hjpData.hnaNew.reduce((sum, value) => sum + (Number(value) || 0), 0);
        const ytdMonths = Math.min(month, 12);
        const ytdExisting = hjpData.hnaExisting.slice(0, ytdMonths).reduce((sum, value) => sum + (Number(value) || 0), 0);
        const ytdNew = hjpData.hnaNew.slice(0, ytdMonths).reduce((sum, value) => sum + (Number(value) || 0), 0);
        [
          [17, annualExisting, annualNew],
          [18, ytdExisting, ytdNew]
        ].forEach(([row, existing, newProduct]) => {
          [existing, newProduct, existing + newProduct].forEach((value, index) => {
            const cell = global.XLSX.utils.encode_cell({ r: row - 1, c: hnaStartColumn - 1 + index });
            sheet[cell] = { t: "n", v: value, z: "#,##0" };
          });
        });
      }
    }
    sheet["!merges"] = [
      {s:{r:2,c:2},e:{r:2,c:4}}, {s:{r:2,c:5},e:{r:2,c:7}}, {s:{r:2,c:8},e:{r:2,c:10}},
      {s:{r:21,c:2},e:{r:21,c:4}}, {s:{r:21,c:5},e:{r:21,c:7}}, {s:{r:21,c:8},e:{r:21,c:10}}, {s:{r:21,c:11},e:{r:21,c:13}}
    ];
    sheet["!cols"] = [{wch:4},{wch:18},...Array(16).fill({wch:16})];
    sheet["!freeze"] = {xSplit:2,ySplit:4};
    const header = {fill:{fgColor:{rgb:"D9EAF7"}},font:{bold:true},alignment:{horizontal:"center",vertical:"center",wrapText:true},border:{top:{style:"thin"},bottom:{style:"thin"},left:{style:"thin"},right:{style:"thin"}}};
    [3,4,22,23,42,43,48,49,59,60].forEach(r=>{ for(let c=1;c<=18;c++){const cell=global.XLSX.utils.encode_cell({r:r-1,c:c-1}); if(sheet[cell]) sheet[cell].s=header;} });
    const index=workbook.SheetNames.indexOf("ETHICAL");
    if(index<0) global.XLSX.utils.book_append_sheet(workbook,sheet,"ETHICAL"); else workbook.Sheets.ETHICAL=sheet;
    if (includeHistory && hjpData && Array.isArray(hjpData._history)) {
      const historyRecords = hjpData._history
        .filter((record) => Number(record.year) < Number(hjpData.year))
        .sort((a, b) => Number(b.year) - Number(a.year));
      let rowOffset = global.XLSX.utils.decode_range(sheet["!ref"] || "A1").e.r + 11;
      for (const record of historyRecords) {
        const archiveBook = global.XLSX.utils.book_new();
        await global.replaceEthicalTemplateSheet(archiveBook, `${record.year}-12`, record, false);
        const archive = archiveBook.Sheets.ETHICAL;
        const archiveRange = global.XLSX.utils.decode_range(archive["!ref"] || "A1");
        Object.keys(archive).forEach((address) => {
          if (address[0] === "!") return;
          const cell = global.XLSX.utils.decode_cell(address);
          sheet[global.XLSX.utils.encode_cell({ r: cell.r + rowOffset, c: cell.c })] = archive[address];
        });
        if (archive["!merges"]) {
          sheet["!merges"] = (sheet["!merges"] || []).concat(archive["!merges"].map((merge) => ({
            s: { r: merge.s.r + rowOffset, c: merge.s.c },
            e: { r: merge.e.r + rowOffset, c: merge.e.c }
          })));
        }
        rowOffset += archiveRange.e.r + 11;
      }
      if (historyRecords.length) {
        sheet["!ref"] = `A1:${global.XLSX.utils.encode_cell({ r: rowOffset - 11, c: 17 })}`;
      }
    }
  };
  const TEMPLATE_BASE64 = "";

  async function readTemplate() {
    try {
      const response = await fetch(new URL("templates/revenue-edp-mnj.ods", document.currentScript?.src || location.href));
      if (response.ok) return await response.arrayBuffer();
    } catch (_) { /* Template tersemat menjadi fallback untuk file:// atau server berbeda. */ }
    const binary = atob(TEMPLATE_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  async function loadRevenueAchievement(period) {
    const year = String(period || "").slice(0, 4);
    const selectedMonth = Number(String(period || "").slice(5, 7));
    const normalize = (value) => String(value == null ? "" : value).trim().toUpperCase().replace(/\s+/g, " ");
    const asAchievement = (rows, sourcePeriod) => ({
      period: sourcePeriod,
      rows: rows.map((record) => {
        if (record.code && Array.isArray(record.revMonths)) return record;
        const cells = [record.gb, record.product_code, record.principal_product_code, record.product_name, record.kategori].map(normalize);
        const gb = cells.map((cell) => cell.match(/^GB\s*(\d+)$/)).find(Boolean);
        let code = "";
        for (const cell of cells) {
          let match = cell.match(/^TOTAL\s+GB\s*(\d+)$/);
          if (match) { code = "gb" + match[1]; break; }
          match = cell.match(/^TOTAL\s+EXISTING\s+GB(?:\s*(\d+))?$/);
          if (match) { code = "existing" + (match[1] || (gb && gb[1]) || ""); break; }
          match = cell.match(/^TOTAL\s+NEW\s+PRODUCT\s+GB(?:\s*(\d+))?$/);
          if (match) { code = "new" + (match[1] || (gb && gb[1]) || ""); break; }
          if (/^TOTAL\s+EXISTING\s+GB\s+ET$/.test(cell)) { code = "ethicalExisting"; break; }
          if (/^TOTAL\s+NEW\s+PRODUCT\s+GB\s+ET$/.test(cell)) { code = "ethicalNew"; break; }
          if (/^TOTAL\s+GB\s+ET$/.test(cell)) { code = "ethicalTotal"; break; }
          if (/^(?:TOTAL\s+)?EXIST(?:ING)?\s+ETH$/.test(cell)) { code = "ethicalExisting"; break; }
          if (/^(?:TOTAL\s+)?(?:NP|NEW\s+PRODUCT)\s+ETH$/.test(cell)) { code = "ethicalNew"; break; }
          if (/^TOTAL\s+ETH$/.test(cell)) { code = "ethicalTotal"; break; }
        }
        // Detail dan subtotal sama-sama punya kolom GB. Hanya gunakan GB
        // generik setelah label subtotal diperiksa agar EXIST/NP tidak tertukar.
        if (!code && gb) code = "gb" + gb[1];
        if (!code) return null;
        return {
          code,
          revMonths: ["rev_jan", "rev_feb", "rev_mar", "rev_apr", "rev_mei", "rev_jun", "rev_jul", "rev_agt", "rev_sep", "rev_okt", "rev_nov", "rev_des"]
          .map((field) => Number(record[field]) || 0)
        };
      }).filter(Boolean)
    });
    const usable = (achievement) => achievement && Array.isArray(achievement.rows)
      && achievement.rows.some((row) => Array.isArray(row.revMonths) && row.revMonths.length === 12);

    const api = location.protocol === "file:"
      ? "http://127.0.0.1:8000/dashboard/revenue_edp_mnj_api.php"
      : new URL("revenue_edp_mnj_api.php", location.href).href;
    const months = Array.from({ length: 12 }, (_, index) => index + 1).sort((a, b) => {
      const aBefore = a <= selectedMonth, bBefore = b <= selectedMonth;
      if (aBefore !== bBefore) return aBefore ? -1 : 1;
      return aBefore ? b - a : a - b;
    });
    for (const month of months) {
      const sourcePeriod = year + "-" + String(month).padStart(2, "0");
      try {
        const response = await fetch(api + "?" + new URLSearchParams({ period: sourcePeriod }));
        if (!response.ok) continue;
        const result = await response.json();
        if (result.success && Array.isArray(result.data) && result.data.length) {
          const achievement = asAchievement(result.data, sourcePeriod);
          if (usable(achievement)) return achievement;
        }
      } catch (_) { /* lanjutkan pencarian ke periode lain */ }
    }
    // Data UNIT & Revenue yang diunggah sebelum pemisahan tabel mungkin masih
    // tersimpan di revenue_selling_out. Baca DB tersebut sebagai migrasi lama.
    const legacyApi = location.protocol === "file:"
      ? "http://127.0.0.1:8000/dashboard/revenue_so_api.php"
      : new URL("revenue_so_api.php", location.href).href;
    for (const month of months) {
      const sourcePeriod = year + "-" + String(month).padStart(2, "0");
      try {
        const response = await fetch(legacyApi + "?" + new URLSearchParams({ period: sourcePeriod }));
        if (!response.ok) continue;
        const result = await response.json();
        if (result.success && Array.isArray(result.data) && result.data.length) {
          const achievement = asAchievement(result.data, sourcePeriod);
          if (usable(achievement)) return achievement;
        }
      } catch (_) { /* coba periode lain dari database lama */ }
    }
    throw new Error("Data REV untuk sheet REVENUE VERSI EDP MNJ tidak ditemukan di database untuk tahun " + year + ". Unggah file melalui UNIT & Revenue.");
  }


  const UNIT_TEMPLATE_BASE64 = "";

  global.replaceUnitTemplateSheet = async function (workbook, period) {
    if (!global.XLSX) throw new Error("Komponen spreadsheet belum dimuat.");
    const requestedPeriod = /^(\d{4})-(0[1-9]|1[0-2])$/.exec(String(period || ""));
    const fallbackDate = new Date();
    const year = requestedPeriod ? Number(requestedPeriod[1]) : fallbackDate.getFullYear();
    const month = requestedPeriod ? Number(requestedPeriod[2]) : fallbackDate.getMonth() + 1;
    const months = ["JANUARI","FEBRUARI","MARET","APRIL","MEI","JUNI","JULI","AGUSTUS","SEPTEMBER","OKTOBER","NOVEMBER","DESEMBER"];
    const monthName = months[month - 1];
    const binary = atob(UNIT_TEMPLATE_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const template = global.XLSX.read(bytes, { type: "array", cellStyles: true, cellNF: true });
    const original = template.Sheets[template.SheetNames[0]];
    const sheet = {};
    Object.entries(original).forEach(([key, value]) => { sheet[key] = key.startsWith("!") || !value || typeof value !== "object" ? value : { ...value }; });
    const setText = (address, value) => { const old = sheet[address] || {}; sheet[address] = { ...old, t: "s", v: value }; delete sheet[address].w; };
    [[1, "REVENUE TAHUN " + year + " (SELL OUT)"], [12, "REVENUE TAHUN " + year + " (SELL IN)"], [26, "TARGET TAHUN " + year], [59, "REVENUE TAHUN " + (year - 1) + " (SELL OUT)"], [70, "REVENUE TAHUN " + (year - 1) + " (SELL IN)"]].forEach(([row, title]) => {
      setText("A" + row, title);
      if (row !== 26) setText("C" + row, monthName);
      setText("C" + (row + 1), "YTD " + monthName);
    });

    // Isi blok SELL OUT pada sheet UNIT dari QTY yang disimpan saat unggah.
    // Ringkasan hanya TOTAL GB 1-6 dan TOTAL ETHICAL.
    const api = location.protocol === "file:"
      ? "http://127.0.0.1:8000/dashboard/unit_api.php"
      : new URL("unit_api.php", location.href).href;
    const qtyFields = ["unit_jan", "unit_feb", "unit_mar", "unit_apr", "unit_mei", "unit_jun", "unit_jul", "unit_agt", "unit_sep", "unit_okt", "unit_nov", "unit_des"];
    const loadUnitYear = async (targetYear, requestedMonth) => {
      const monthsToCheck = Array.from({ length: 12 }, (_, i) => i + 1).sort((a, b) => {
        const aPast = a <= requestedMonth, bPast = b <= requestedMonth;
        return aPast !== bPast ? (aPast ? -1 : 1) : (aPast ? b - a : a - b);
      });
      let lastMessage = "";
      for (const sourceMonth of monthsToCheck) {
        const sourcePeriod = targetYear + "-" + String(sourceMonth).padStart(2, "0");
        try {
          const response = await fetch(api + "?" + new URLSearchParams({ period: sourcePeriod }));
          const result = await response.json();
          if (!response.ok || !result.success) { lastMessage = result.message || ("API mengembalikan HTTP " + response.status); continue; }
          if (Array.isArray(result.data) && result.data.length) return result.data;
        } catch (error) { lastMessage = error.message || "API tidak dapat dihubungi"; }
      }
      return { error: lastMessage || "Tidak ada baris data pada periode tahun tersebut." };
    };
    const sourceRows = await loadUnitYear(year, month);
    if (!Array.isArray(sourceRows)) throw new Error("QTY tahun " + year + " tidak terbaca untuk sheet UNIT. " + sourceRows.error + " Pastikan data UNIT & Revenue sudah berhasil diunggah ke database.");
    const normalize = (value) => String(value == null ? "" : value).trim().toUpperCase().replace(/\s+/g, " ");
    const readQtyTotals = (rows) => {
      const totals = new Map();
      rows.forEach((record) => {
        const cells = [record.gb, record.product_code, record.principal_product_code, record.product_name, record.kategori].map(normalize);
        let code = "";
        for (const value of cells) {
          const match = value.match(/^TOTAL\s+GB\s*(\d+)$/);
          if (match) { code = "gb" + match[1]; break; }
          if (/^TOTAL\s+(?:GB\s*)?ET(?:HICAL)?$/.test(value)) { code = "ethical"; break; }
        }
        if (!code) return;
        const amounts = qtyFields.map((field) => Number(record[field]) || 0);
        const sum = totals.get(code) || Array(12).fill(0);
        for (let i = 0; i < 12; i++) sum[i] += amounts[i];
        totals.set(code, sum);
      });
      return totals;
    };
    const writeQtyTotals = (totals, firstRow, ytdMonth) => {
      const unitRows = [["gb1", firstRow], ["gb2", firstRow + 1], ["gb3", firstRow + 2], ["gb4", firstRow + 3], ["gb5", firstRow + 4], ["gb6", firstRow + 5], ["ethical", firstRow + 6]];
      unitRows.forEach(([code, row]) => {
        const values = totals.get(code);
        if (!values) return;
        const total = values.reduce((sum, value) => sum + value, 0);
        const ytd = values.slice(0, ytdMonth).reduce((sum, value) => sum + value, 0);
        const putNumber = (column, value) => {
          const address = global.XLSX.utils.encode_cell({ r: row, c: column });
          sheet[address] = { ...(sheet[address] || {}), t: "n", v: value, z: "#,##0;[Red]-#,##0" };
          delete sheet[address].w;
        };
        putNumber(2, ytd);
        values.forEach((value, index) => putNumber(3 + index, value));
        putNumber(15, total);
      });
    };
    writeQtyTotals(readQtyTotals(sourceRows), 2, month);
    const previousRows = await loadUnitYear(year - 1, 12);
    if (Array.isArray(previousRows)) writeQtyTotals(readQtyTotals(previousRows), 60, month);
    const index = workbook.SheetNames.indexOf("UNIT");
    if (index < 0) global.XLSX.utils.book_append_sheet(workbook, sheet, "UNIT");
    else workbook.Sheets.UNIT = sheet;
  };

  global.replaceEdpTemplateSheet = async function (workbook, period, revenueAchievement) {
    if (!global.XLSX) throw new Error("Komponen spreadsheet belum dimuat.");
    const templateWorkbook = global.XLSX.read(await readTemplate(), {
      type: "array",
      cellStyles: true,
      cellNF: true
    });
    const sourceSheet = templateWorkbook.Sheets[templateWorkbook.SheetNames[0]];
    if (!sourceSheet) throw new Error("Sheet pada template Revenue EDP MNJ tidak ditemukan.");

    const sheet = {};
    Object.entries(sourceSheet).forEach(([key, value]) => {
      sheet[key] = key.startsWith("!") || !value || typeof value !== "object" ? value : { ...value };
    });
    const requestedPeriod = /^(\d{4})-(0[1-9]|1[0-2])$/.exec(String(period || ""));
    const fallbackDate = new Date();
    const reportYear = requestedPeriod ? Number(requestedPeriod[1]) : fallbackDate.getFullYear();
    const reportMonth = requestedPeriod ? Number(requestedPeriod[2]) : fallbackDate.getMonth() + 1;
    const previousYear = reportYear - 1;
    // Sheet EDP harus selalu memakai data EDP dari database, bukan achievement
    // Sell Out yang kebetulan sedang dipakai halaman dashboard.
    try {
      revenueAchievement = await loadRevenueAchievement(period);
    } catch (error) {
      // Template tetap wajib disertakan walaupun API/database belum tersedia.
      console.warn("Data REV EDP tidak tersedia; struktur template tetap dimasukkan:", error);
      revenueAchievement = null;
    }
    let previousRevenueAchievement = null;
    try {
      previousRevenueAchievement = await loadRevenueAchievement(previousYear + "-12");
    } catch (error) {
      console.warn("Data REV EDP tahun sebelumnya tidak tersedia:", error);
    }
    const monthNames = ["JANUARI", "FEBRUARI", "MARET", "APRIL", "MEI", "JUNI", "JULI", "AGUSTUS", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DESEMBER"];
    const monthName = monthNames[reportMonth - 1];
    const replaceCellText = (address, value) => {
      const oldCell = sheet[address] || {};
      sheet[address] = { ...oldCell, t: "s", v: value };
      delete sheet[address].w;
    };
    [
      [1, "REVENUE TAHUN " + reportYear],
      [32, "BIAYA TAHUN " + reportYear],
      [61, "MCM TAHUN " + reportYear],
      [91, "TARGET SELL OUT " + previousYear],
      [118, "REVENUE TAHUN " + previousYear],
      [149, "BIAYA TAHUN " + previousYear],
      [178, "MCM TAHUN " + previousYear]
    ].forEach(([row, label]) => {
      replaceCellText("A" + row, label);
      replaceCellText("C" + row, monthName);
      replaceCellText("C" + (row + 1), "YTD " + monthName);
    });

    // Isi blok REVENUE tahun berjalan dengan ringkasan REV yang sudah dibaca
    // saat ekspor. Kolom setelah bulan periode sengaja dikosongkan.
    if (revenueAchievement && Array.isArray(revenueAchievement.rows)) {
      const monthKeys = ["JANUARI", "FEBRUARI", "MARET", "APRIL", "MEI", "JUNI", "JULI", "AGUSTUS", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DESEMBER"];
      const sourcePeriod = /^(\d{4})-(0[1-9]|1[0-2])$/.exec(String(revenueAchievement.period || ""));
      const revenueMonth = sourcePeriod && Number(sourcePeriod[1]) === reportYear
        ? Math.min(reportMonth, Number(sourcePeriod[2]))
        : reportMonth;
      if (revenueMonth < reportMonth) {
        replaceCellText("C1", monthNames[revenueMonth - 1]);
        replaceCellText("C2", "YTD " + monthNames[revenueMonth - 1]);
      }
      const grid = global.XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "", raw: true });
      const normalize = (value) => String(value == null ? "" : value).trim().toUpperCase().replace(/\s+/g, " ");
      let headerIndex = grid.findIndex((row) => row.some((value) => normalize(value) === "JANUARI")
        && row.some((value) => normalize(value) === "DESEMBER"));
      // Pada template ODS, SheetJS kadang tidak mengembalikan teks bulan
      // dari baris header. Layout EDP baku memakai row 2 dan kolom D:O.
      if (headerIndex < 0) headerIndex = 1;
      {
        const header = (grid[headerIndex] || []).map(normalize);
        const monthColumns = monthKeys.map((name) => header.indexOf(name));
        if (monthColumns.some((column) => column < 0)) monthColumns.splice(0, 12, ...Array.from({ length: 12 }, (_, index) => index + 3));
        // XLSX tidak selalu mengevaluasi formula header YTD pada template.
        // Kolom YTD berada tepat sebelum kolom Januari, jadi gunakan posisi
        // itu sebagai fallback tanpa bergantung pada hasil kalkulasi formula.
        const detectedYtdColumn = header.findIndex((value) => value.startsWith("YTD "));
        const ytdColumn = detectedYtdColumn >= 0 ? detectedYtdColumn : 2;
        const detectedTotalColumn = header.indexOf("TOTAL");
        const totalColumn = detectedTotalColumn >= 0 ? detectedTotalColumn : 15;
        const rowIndexes = new Map();
        for (let r = headerIndex + 1; r < grid.length; r++) {
          const label = normalize(grid[r][1] || grid[r][0]);
          if (/^(?:BIAYA|MCM|TARGET|REVENUE) TAHUN \d{4}/.test(label)) break;
          if (label) rowIndexes.set(label, r);
        }
        // Isi posisi standar template bila label tidak terbaca saat konversi ODS.
        for (let gb = 1; gb <= 6; gb++) {
          const base = 2 + (gb - 1) * 4;
          rowIndexes.set("EXIST GB " + gb, rowIndexes.get("EXIST GB " + gb) ?? base);
          rowIndexes.set("NP GB " + gb, rowIndexes.get("NP GB " + gb) ?? base + 1);
          rowIndexes.set("TOTAL GB " + gb, rowIndexes.get("TOTAL GB " + gb) ?? base + 2);
        }
        rowIndexes.set("EXIST ETHICAL", rowIndexes.get("EXIST ETHICAL") ?? 26);
        rowIndexes.set("NP ETHICAL", rowIndexes.get("NP ETHICAL") ?? 27);
        rowIndexes.set("TOTAL ETHICAL", rowIndexes.get("TOTAL ETHICAL") ?? 28);
        const monthly = new Map();
        revenueAchievement.rows.forEach((record) => {
          const code = String(record.code || "");
          if (!code) return;
          const values = Array.isArray(record.revMonths) ? record.revMonths : [];
          const aggregate = monthly.get(code) || Array(12).fill(0);
          for (let i = 0; i < 12; i++) aggregate[i] += Number(values[i]) || 0;
          monthly.set(code, aggregate);
        });
        const readMonths = (code, fallbackCodes) => {
          if (monthly.has(code)) return monthly.get(code);
          const matches = fallbackCodes.map((key) => monthly.get(key)).filter(Boolean);
          return matches.length ? Array.from({ length: 12 }, (_, i) => matches.reduce((sum, values) => sum + values[i], 0)) : null;
        };
        const sumMonths = (codes) => {
          const matches = codes.map((code) => monthly.get(code)).filter(Boolean);
          return matches.length ? Array.from({ length: 12 }, (_, i) => matches.reduce((sum, values) => sum + (Number(values[i]) || 0), 0)) : null;
        };
        const outputRows = [];
        for (let gb = 1; gb <= 6; gb++) {
          outputRows.push(["EXIST GB " + gb, readMonths("existing" + gb, [])]);
          outputRows.push(["NP GB " + gb, readMonths("new" + gb, [])]);
          outputRows.push(["TOTAL GB " + gb, sumMonths(["existing" + gb, "new" + gb])]);
        }
        outputRows.push(["EXIST ETHICAL", readMonths("ethicalExisting", [])]);
        outputRows.push(["NP ETHICAL", readMonths("ethicalNew", [])]);
        outputRows.push(["TOTAL ETHICAL", sumMonths(["ethicalExisting", "ethicalNew"])]);
        const setNumber = (row, column, value) => {
          if (column < 0) return;
          const address = global.XLSX.utils.encode_cell({ r: row, c: column });
          const oldCell = sheet[address] || {};
          sheet[address] = { ...oldCell, t: "n", v: value, z: "#,##0;[Red]-#,##0" };
          delete sheet[address].w;
        };
        const setBlank = (row, column) => {
          if (column < 0) return;
          const address = global.XLSX.utils.encode_cell({ r: row, c: column });
          const oldCell = sheet[address] || {};
          sheet[address] = { ...oldCell, t: "s", v: "" };
          delete sheet[address].w;
        };
        let rowsWritten = 0;
        outputRows.forEach(([label, values]) => {
          const row = rowIndexes.get(label);
          if (row == null) return;
          if (!values) {
            monthColumns.forEach((column) => setBlank(row, column));
            setBlank(row, ytdColumn);
            setBlank(row, totalColumn);
            return;
          }
          const ytd = values.slice(0, revenueMonth).reduce((sum, value) => sum + (Number(value) || 0), 0);
          monthColumns.forEach((column, index) => {
            if (index < revenueMonth) setNumber(row, column, Number(values[index]) || 0);
            else setBlank(row, column);
          });
          setNumber(row, ytdColumn, ytd);
          setNumber(row, totalColumn, ytd);
          rowsWritten++;
        });
        // Terapkan pemisah ribuan pada seluruh area angka blok REVENUE tahun berjalan.
        // Nilai tetap numerik agar tetap bisa dihitung di spreadsheet.
        for (let row = headerIndex + 1; row < grid.length; row++) {
          const label = normalize(grid[row][1] || grid[row][0]);
          if (/^(?:BIAYA|MCM|TARGET|REVENUE) TAHUN \d{4}/.test(label)) break;
          if (!label) continue;
          [ytdColumn, ...monthColumns, totalColumn].forEach((column) => {
            if (column < 0) return;
            const address = global.XLSX.utils.encode_cell({ r: row, c: column });
            if (sheet[address] && (sheet[address].t === "n" || typeof sheet[address].v === "number")) {
              sheet[address].z = "#,##0;[Red]-#,##0";
              delete sheet[address].w;
            }
          });
        }
        if (!rowsWritten) console.warn("Baris REVENUE VERSI EDP MNJ tidak ditemukan pada template.");
      }
    }
    // Isi blok tahun sebelumnya dari upload EDP periode tahun tersebut.
    // Ini membuat upload Desember 2025 tetap muncul pada blok REVENUE 2025
    // saat workbook tahun 2026 diunduh.
    if (previousRevenueAchievement && Array.isArray(previousRevenueAchievement.rows)) {
      const grid = global.XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "", raw: true });
      const normalize = (value) => String(value == null ? "" : value).trim().toUpperCase().replace(/\s+/g, " ");
      const monthNames = ["JANUARI", "FEBRUARI", "MARET", "APRIL", "MEI", "JUNI", "JULI", "AGUSTUS", "SEPTEMBER", "OKTOBER", "NOVEMBER", "DESEMBER"];
      const sectionIndex = grid.findIndex((row) => row.some((value) => normalize(value) === "REVENUE TAHUN " + previousYear));
      if (sectionIndex >= 0) {
        let headerIndex = -1;
        for (let r = sectionIndex; r < Math.min(grid.length, sectionIndex + 6); r++) {
          const values = (grid[r] || []).map(normalize);
          if (values.includes("JANUARI") && values.includes("DESEMBER")) { headerIndex = r; break; }
        }
        if (headerIndex >= 0) {
          const header = grid[headerIndex].map(normalize);
          const monthColumns = monthNames.map((name) => header.indexOf(name));
          if (monthColumns.some((column) => column < 0)) monthColumns.splice(0, 12, ...Array.from({ length: 12 }, (_, index) => index + 3));
          const ytdColumn = Math.max(0, header.findIndex((value) => value.startsWith("YTD ")));
          const totalColumn = Math.max(0, header.indexOf("TOTAL"));
          const rowIndexes = new Map();
          for (let r = headerIndex + 1; r < grid.length; r++) {
            const label = normalize(grid[r][1] || grid[r][0]);
            if (/^(?:BIAYA|MCM|TARGET|REVENUE) TAHUN \d{4}/.test(label)) break;
            if (label) rowIndexes.set(label, r);
          }
          for (let gb = 1; gb <= 6; gb++) {
            const base = headerIndex + 1 + (gb - 1) * 4;
            rowIndexes.set("EXIST GB " + gb, rowIndexes.get("EXIST GB " + gb) ?? base);
            rowIndexes.set("NP GB " + gb, rowIndexes.get("NP GB " + gb) ?? base + 1);
            rowIndexes.set("TOTAL GB " + gb, rowIndexes.get("TOTAL GB " + gb) ?? base + 2);
          }
          rowIndexes.set("EXIST ETHICAL", rowIndexes.get("EXIST ETHICAL") ?? headerIndex + 25);
          rowIndexes.set("NP ETHICAL", rowIndexes.get("NP ETHICAL") ?? headerIndex + 26);
          rowIndexes.set("TOTAL ETHICAL", rowIndexes.get("TOTAL ETHICAL") ?? headerIndex + 27);
          const monthly = new Map();
          previousRevenueAchievement.rows.forEach((record) => {
            const values = Array.isArray(record.revMonths) ? record.revMonths : [];
            if (!record.code) return;
            const aggregate = monthly.get(record.code) || Array(12).fill(0);
            for (let i = 0; i < 12; i++) aggregate[i] += Number(values[i]) || 0;
            monthly.set(record.code, aggregate);
          });
          const rows = [];
          for (let gb = 1; gb <= 6; gb++) {
            rows.push(["EXIST GB " + gb, monthly.get("existing" + gb)]);
            rows.push(["NP GB " + gb, monthly.get("new" + gb)]);
            const parts = [monthly.get("existing" + gb), monthly.get("new" + gb)].filter(Boolean);
            rows.push(["TOTAL GB " + gb, parts.length ? Array.from({ length: 12 }, (_, i) => parts.reduce((sum, values) => sum + (Number(values[i]) || 0), 0)) : null]);
          }
          rows.push(["EXIST ETHICAL", monthly.get("ethicalExisting")]);
          rows.push(["NP ETHICAL", monthly.get("ethicalNew")]);
          const ethicalParts = [monthly.get("ethicalExisting"), monthly.get("ethicalNew")].filter(Boolean);
          rows.push(["TOTAL ETHICAL", ethicalParts.length ? Array.from({ length: 12 }, (_, i) => ethicalParts.reduce((sum, values) => sum + (Number(values[i]) || 0), 0)) : null]);
          const setValue = (row, column, value) => {
            if (column < 0) return;
            const address = global.XLSX.utils.encode_cell({ r: row, c: column });
            const oldCell = sheet[address] || {};
            sheet[address] = { ...oldCell, t: "n", v: value, z: "#,##0;[Red]-#,##0" };
            delete sheet[address].w;
          };
          rows.forEach(([label, values]) => {
            const row = rowIndexes.get(label);
            if (row == null || !values) return;
            const ytd = values.slice(0, reportMonth).reduce((sum, value) => sum + (Number(value) || 0), 0);
            monthColumns.forEach((column, index) => setValue(row, column, Number(values[index]) || 0));
            setValue(row, ytdColumn, ytd);
            setValue(row, totalColumn, values.reduce((sum, value) => sum + (Number(value) || 0), 0));
          });
        }
      }
    }
    const existingIndex = workbook.SheetNames.indexOf(TEMPLATE_NAME);
    if (existingIndex < 0) {
      global.XLSX.utils.book_append_sheet(workbook, sheet, TEMPLATE_NAME);
    } else {
      workbook.Sheets[TEMPLATE_NAME] = sheet;
    }
  };
})(window);
